    internal static Control Color(string name, double size = 24)
    {
        var key = "FluentArtwork" + name;
        if (Application.Current?.Resources.TryGetResource(key, Application.Current.ActualThemeVariant, out var value) != true || value is not IImage image)
            throw new InvalidOperationException("Illustration Fluent absente : " + name);
        return new Image { Source = image, Width = size, Height = size, Stretch = Stretch.Uniform, IsHitTestVisible = false };
    }

    internal static Control Line(string name, double size = 20, IBrush? brush = null) => new PathIcon
    {
        Data = Lines[name], Width = size, Height = size, Foreground = brush ?? OwnerPalette.Muted, IsHitTestVisible = false
    };
